<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {useRoute} from 'vue-router';
import {reviewApi,type IncidentFilters} from '../../api/review';
import {useReplayStore,reviewError} from '../../store/useReplayStore';
import {pipelineApi} from '../../api/pipelines';
import type {PipelineNetwork} from '../../types/pipeline';
import {incidentTypeLabels,incidentStatusLabels,workOrderStatusLabels,type Incident,type TimelineEvent,type KeyMoment,type WorkOrder,type WorkOrderStatus} from '../../types/review';
import DigitalTwinScene from '../../components/digital-twin/DigitalTwinScene.vue';
import ReplayChart from './components/ReplayChart.vue';
import RecordValue from './components/RecordValue.vue';
import './review.css';
const store=useReplayStore(),route=useRoute();const items=ref<Incident[]>([]),total=ref(0),listLoading=ref(false),listError=ref(''),busy=ref(false),actionError=ref(''),actionMessage=ref('');
const filters=ref({type:'',status:'',keyword:'',start_time:'',end_time:''}),offset=ref(0);const pageSize=30;
const network=ref<PipelineNetwork>({nodes:[],edges:[],valves:[]});const assignee=ref<Record<string,string>>({}),result=ref<Record<string,string>>({}),closeResult=ref(''),reportBusy=ref(false),chartTab=ref(0);
let listGeneration=0,disposed=false;const controller=new AbortController();
const isFlood=computed(()=>store.incident?.incident_type==='FLOOD');
const chartTabs=computed(()=>isFlood.value?[{label:'雨量',unit:'mm/h',metric:'flood.rainfall'},{label:'水位',unit:'cm',metric:'flood.waterLevel'},{label:'有效排水能力',unit:'m³/s',metric:'flood.effectivePumpCapacity'},{label:'规则风险',unit:'分',metric:'flood.riskScore'}]:[{label:'压力',unit:'MPa',metric:'leak.downstreamPressure'},{label:'管段流量',unit:'m³/h',metric:'leak.pipelineFlow'},{label:'异常匹配度',unit:'0–1',metric:'leak.detectionScore'},{label:'泄漏规则风险',unit:'分',metric:'leak.riskScore'}]);
const tab=computed(()=>chartTabs.value[chartTab.value]??chartTabs.value[0]!);
const scene=computed(()=>store.sceneState as Record<string,Record<string,unknown>>);
const current=computed(()=>isFlood.value?scene.value.flood:scene.value.leak);
const activeTimeline=computed(()=>store.timelineEvents.filter(e=>e.simulation_time!==null&&e.simulation_time<=store.currentTime).at(-1));
const focusId=computed(()=>String(activeTimeline.value?.payload?.focus_target_id??''));
const missing=computed(()=>Array.from(new Set([...(store.replay?.metadata.missing_fields??[]),...(store.currentSnapshot?.missing_fields??[])])));
const responseLabels:Record<string,string>={time_to_detect_seconds:'发现耗时',time_to_confirm_seconds:'确认耗时',time_to_response_seconds:'检测后响应耗时',time_to_stabilize_seconds:'达到稳定耗时',total_incident_duration_seconds:'事件总时长'};
const peakLabels:Record<string,string>={peak_risk:'峰值风险 / 分',peak_water_level:'峰值水位 / cm',max_water_area:'最大积水面积 / m²',max_rainfall:'最大雨量 / mm/h',min_p03_efficiency:'P03 最低效率',min_pressure:'最低压力 / MPa',max_flow:'最大流量 / m³/h',max_detection_score:'最高异常匹配度',max_affected_buildings:'最大影响建筑 / 栋'};
const selectedPeaks=computed(()=>Object.entries(store.metrics?.peak_metrics??{}).filter(([key])=>isFlood.value?['peak_risk','peak_water_level','max_water_area','max_rainfall','min_p03_efficiency'].includes(key):['peak_risk','min_pressure','max_flow','max_detection_score','max_affected_buildings'].includes(key)));
const prediction=computed(()=>store.metrics?.prediction_review);
const executionCards=computed(()=>(store.incident?.executions??[]).map(e=>({id:String(e.id??''),data:(e.execution??e.execution_json??e) as Record<string,unknown>})));
const comparisons=computed(()=>(store.incident?.comparisons??[]).map(c=>({id:String(c.id??''),data:(c.comparison_json??c.result_json??(c.results&&!Array.isArray(c.results)?c.results:c)) as Record<string,unknown>})));
function number(value:unknown,digits=2){return typeof value==='number'&&Number.isFinite(value)?value.toFixed(digits):'未记录';}
function date(value?:string|null){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'未记录';}
function elapsed(seconds:number|null|undefined){if(seconds===null||seconds===undefined||!Number.isFinite(seconds))return '未记录';const s=Math.max(0,Math.round(seconds));return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`;}
function duration(incident:Incident){return incident.closed_at&&incident.started_at?elapsed((Date.parse(incident.closed_at)-Date.parse(incident.started_at))/1000):incident.status==='ABORTED'?'已中断 · 结束时间未记录':'尚未关闭';}
function tone(type:string){if(/CLOSED|STABILIZED|CONTAINED/.test(type))return 'recovery';if(/FAULT|CONFIRMED/.test(type))return 'critical';if(/RISK|PEAK/.test(type))return 'risk';if(/PLAN|EXECUTION|ACTION|VALVE|ENTRANCE|WORK_ORDER/.test(type))return 'emergency';return 'detection';}
function markerPosition(time:number|null){const range=store.endTime-store.startTime;return `${range&&time!==null?Math.max(0,Math.min(100,(time-store.startTime)/range*100)):0}%`;}
function jump(moment:TimelineEvent|KeyMoment){if(moment.simulation_time!==null){store.pause();store.seek(moment.simulation_time);}}
function quick(kind:string){if(kind==='start'){store.pause();store.seek(store.startTime);return;}if(kind==='end'){store.pause();store.seek(store.endTime);return;}const pattern:Record<string,RegExp>={confirm:/CONFIRMED|ANOMALY_DETECTED/,peak:/PEAK_RISK|PEAK_WATER/,response:/EXECUTION_STARTED|ACTION_STARTED|VALVE_CLOSED/,stable:/RISK_STABILIZED|CONTAINED/};const found=store.keyMoments.find(e=>pattern[kind]?.test(e.event_type??e.type??''));if(found)jump(found);}
function quickAvailable(kind:string){if(['start','end'].includes(kind))return !!store.snapshots.length;const pattern:Record<string,RegExp>={confirm:/CONFIRMED|ANOMALY_DETECTED/,peak:/PEAK_RISK|PEAK_WATER/,response:/EXECUTION_STARTED|ACTION_STARTED|VALVE_CLOSED/,stable:/RISK_STABILIZED|CONTAINED/};return store.keyMoments.some(e=>e.simulation_time!==null&&pattern[kind]?.test(e.event_type??e.type??''));}
async function loadList(reset=false){const token=++listGeneration;if(reset)offset.value=0;listLoading.value=true;listError.value='';const params:IncidentFilters={limit:pageSize,offset:offset.value};for(const [key,value] of Object.entries(filters.value))if(value)(params as Record<string,unknown>)[key]=key.endsWith('_time')?new Date(value).toISOString():value;try{const response=await reviewApi.list(params,controller.signal);if(token===listGeneration){items.value=response.items;total.value=response.total;}}catch(e){if(!disposed&&token===listGeneration)listError.value=reviewError(e);}finally{if(token===listGeneration)listLoading.value=false;}}
async function select(incident:Incident){chartTab.value=0;actionError.value='';actionMessage.value='';closeResult.value='';await store.select(incident.id);}
async function action(run:()=>Promise<unknown>,message:string){if(busy.value)return;busy.value=true;actionError.value='';actionMessage.value='';try{await run();if(disposed)return;await store.refresh();await loadList();actionMessage.value=message;}catch(e){if(!disposed)actionError.value=reviewError(e);}finally{busy.value=false;}}
function updateOrder(order:WorkOrder,status:WorkOrderStatus){const who=assignee.value[order.id]??order.assignee??'';const note=result.value[order.id]??'';if(status==='ASSIGNED'&&!who.trim()){actionError.value='请填写接单班组。';return;}if(status==='COMPLETED'&&!note.trim()){actionError.value='请填写处理结果后完成工单。';return;}void action(()=>reviewApi.patchWorkOrder(order.id,status,who.trim(),note.trim()),'工单状态已保存。');}
function closeIncident(){if(!store.incident||!closeResult.value.trim()){actionError.value='请填写事件关闭说明。';return;}if(window.confirm('确认关闭该软件仿真事件？关闭后事件将进入历史复盘，不再作为当前活动事故。'))void action(()=>reviewApi.close(store.incident!.id,closeResult.value.trim()),'事件已关闭并保留历史档案。');}
async function generateReport(){if(!store.incident||reportBusy.value)return;reportBusy.value=true;actionError.value='';const id=store.selectedId;try{const report=await reviewApi.generate(id);if(id===store.selectedId&&!disposed)store.report=report;}catch(e){if(!disposed)actionError.value=reviewError(e);}finally{reportBusy.value=false;}}
function rows(value:unknown):Record<string,unknown>[]{return Array.isArray(value)?value.filter(x=>x&&typeof x==='object'):[];}
function branches(value:Record<string,unknown>){return [value.baseline,...rows(value.results)].filter(x=>x&&typeof x==='object') as Record<string,unknown>[];}
function briefExecution(value:Record<string,unknown>){return Object.fromEntries(['plan_code','plan_name','status','phase','initial_risk','started_at','operator','valves','affectedBuildings'].filter(key=>key in value).map(key=>[key,value[key]]));}
function effect(value:Record<string,unknown>|null|undefined){if(!value)return null;const keys=isFlood.value?['timestamp','simulation_time','risk_score','water_level','pump_capacity','rainfall']:['timestamp','simulation_time','risk_score','pressure','flow','leak_flow','service_status','interrupted_buildings','estimated_service_loss'];return Object.fromEntries(keys.map(key=>[key,value[key]??null]));}
onMounted(async()=>{await loadList();const id=typeof route.query.incident==='string'?route.query.incident:'';if(id&&!disposed)void store.select(id);try{network.value=await pipelineApi.network(controller.signal);}catch{if(!disposed)listError.value='静态管网资产加载失败，历史指标仍可查看。';}});
onBeforeUnmount(()=>{disposed=true;listGeneration++;controller.abort();store.dispose();});
</script>
<template>
<section class="review-page" data-testid="review-page">
 <header class="page-heading"><div><span class="eyebrow">TIMELINE REPLAY · INCIDENT REVIEW</span><h2>事件复盘与工单中心</h2><p>持久化事故档案 · 历史回放 · 人工确认闭环</p></div><b class="review-mode">历史回放 · 独立于实时场景</b></header>
 <div class="review-layout">
 <aside class="panel review-sidebar"><header><h3>事件档案</h3><small data-testid="incident-total">{{total}} 条</small></header>
 <form class="review-filters" @submit.prevent="loadList(true)"><div><select v-model="filters.type" aria-label="事件类型"><option value="">全部类型</option><option value="FLOOD">暴雨内涝</option><option value="PIPELINE_LEAK">管网泄漏</option></select><select v-model="filters.status" aria-label="事件状态"><option value="">全部状态</option><option v-for="(label,key) in incidentStatusLabels" :key="key" :value="key">{{label}}</option></select></div><input v-model="filters.keyword" aria-label="事件关键词" placeholder="编号、标题或位置"/><label>开始日期<input v-model="filters.start_time" type="datetime-local" aria-label="筛选开始时间"/></label><label>结束日期<input v-model="filters.end_time" type="datetime-local" aria-label="筛选结束时间"/></label><button :disabled="listLoading" type="submit">筛选事件</button></form>
 <p v-if="listError" role="alert">{{listError}}</p><p v-if="!items.length&&!listLoading" class="review-empty">暂无符合条件的事故。运行内涝或泄漏场景后，已保存的历史会出现在这里。</p>
 <div class="review-incident-list"><button v-for="incident in items" :key="incident.id" class="review-incident" :class="{selected:store.selectedId===incident.id}" :data-incident-id="incident.id" :data-incident-type="incident.incident_type" @click="select(incident)"><span>{{incident.incident_code}}</span><strong>{{incident.title}}</strong><small>{{incidentTypeLabels[incident.incident_type]}} · {{incident.area_id??'位置未记录'}}</small><div><b :class="incident.status.toLowerCase()">{{incidentStatusLabels[incident.status]}}</b><span>峰值 {{number(incident.peak_risk,1)}}</span></div><time>{{date(incident.started_at)}}</time><small>{{duration(incident)}}</small></button></div>
 <div class="review-pagination"><button :disabled="offset===0||listLoading" @click="offset-=pageSize;loadList()">上一页</button><span>{{Math.floor(offset/pageSize)+1}}</span><button :disabled="offset+pageSize>=total||listLoading" @click="offset+=pageSize;loadList()">下一页</button></div></aside>
 <main class="review-content">
 <div v-if="!store.selectedId" class="panel review-welcome"><span>HISTORY → REPLAY → REVIEW</span><h3>选择一条事故，查看完整处置过程</h3><p>回放读取数据库快照，不推进仿真，不改变当前设备或阀门。已中断事故按 ABORTED 保留，关闭事故按 CLOSED 归档。</p><p>旧历史缺失的设备、阀门或阶段记录会标注“未记录”。</p></div>
 <template v-else>
 <p v-if="store.loading" class="review-notice">正在读取事件历史…</p><p v-if="store.error" role="alert">{{store.error}}</p><p v-for="warning in store.warnings" :key="warning" class="review-notice">{{warning}}</p>
 <header class="review-detail-heading"><div><small>{{store.incident?.incident_code??'正在读取'}} · {{store.incident?incidentTypeLabels[store.incident.incident_type]:''}}</small><h3>{{store.incident?.title??'事故历史'}}</h3></div><b>{{store.incident?incidentStatusLabels[store.incident.status]:''}}</b></header>
 <div class="review-stage-grid"><div class="review-scene-wrap"><DigitalTwinScene data-mode="replay" :replay-type="store.incident?.incident_type" :replay-incident-id="store.selectedId" :replay-state="store.sceneState" :replay-playing="store.isPlaying" :replay-time="store.currentTime" :replay-focus-id="focusId" :pipeline-network="network" :initial-underground="store.incident?.incident_type==='PIPELINE_LEAK'"/><div class="review-scene-label">历史回放 · {{store.currentGap?'采样缺口 · 保留前次记录':store.isPlaying?'播放中':'已暂停'}}</div></div>
 <aside class="panel review-summary" data-testid="review-summary"><h3>回放节点</h3><strong class="review-clock" data-testid="replay-time">T+{{elapsed(store.currentTime)}}</strong><time>{{date(store.originalTime)}}</time><p class="review-muted">原始记录时间{{store.currentGap?'（缺口内保持）':''}}</p><dl><div><dt>当前记录风险</dt><dd>{{number(current?.riskScore,1)}}</dd></div><template v-if="isFlood"><div><dt>水位</dt><dd>{{number(current?.waterLevel)}} cm</dd></div><div><dt>积水面积</dt><dd>{{number(current?.waterArea,1)}} m²</dd></div><div><dt>有效排水能力</dt><dd>{{number(current?.effectivePumpCapacity,3)}} m³/s</dd></div><div><dt>入口状态</dt><dd>{{current?.entranceClosed===true?'封控':current?.entranceClosed===false?'开放':'未记录'}}</dd></div></template><template v-else><div><dt>下游压力</dt><dd>{{number(current?.downstreamPressure,3)}} MPa</dd></div><div><dt>估算泄漏流量</dt><dd>{{number(current?.estimatedLeakFlow)}} m³/h</dd></div><div><dt>异常匹配度</dt><dd>{{number(current?.detectionScore,3)}}</dd></div><div><dt>供水状态</dt><dd>{{current?.serviceStatus??'未记录'}}</dd></div><div><dt>Top 1</dt><dd>{{rows(current?.suspectedSegments)[0]?.pipeline_id??'未记录'}}</dd></div></template></dl><p>{{activeTimeline?.title??'尚无该时刻关键事件'}}</p><small>快照 {{store.snapshots.length?store.currentIndex+1:0}} / {{store.snapshots.length}}</small></aside></div>
 <section class="panel review-player" data-testid="replay-player"><div class="review-toolbar"><button data-testid="replay-play" @click="store.play" :disabled="store.loading||store.isPlaying||store.snapshots.length<2">播放</button><button data-testid="replay-pause" @click="store.pause" :disabled="!store.isPlaying">暂停</button><button data-testid="replay-stop" @click="store.stop" :disabled="!store.snapshots.length">停止并回到开始</button><label>播放速度<select :value="store.playbackSpeed" aria-label="回放速度" @change="store.setSpeed(Number(($event.target as HTMLSelectElement).value))"><option v-for="speed in [.5,1,2,5]" :key="speed" :value="speed">{{speed}}×</option></select></label><small>{{elapsed(store.currentTime)}} / {{elapsed(store.endTime-store.startTime)}} · {{store.isPlaying?'播放中':'已暂停'}}</small></div>
 <div class="review-scrubber"><input data-testid="replay-scrubber" type="range" aria-label="历史时间轴" :min="store.startTime" :max="Math.max(store.startTime+.001,store.endTime)" :value="store.currentTime" step="0.1" @input="store.pause();store.seek(Number(($event.target as HTMLInputElement).value))"/><div class="review-markers"><button v-for="moment in store.keyMoments.filter(m=>m.simulation_time!==null)" :key="moment.id??`${moment.title}-${moment.simulation_time}`" :class="tone(moment.event_type??moment.type??'')" :style="{left:markerPosition(moment.simulation_time)}" :title="`${moment.title} · T+${elapsed(moment.simulation_time)}`" :aria-label="`跳转：${moment.title}`" @click="jump(moment)"></button></div></div>
 <div class="review-toolbar review-quick-jump"><button v-for="(label,key) in {start:'开始',confirm:'异常确认',peak:'峰值',response:'处置',stable:'稳定',end:'结束'}" :key="key" :disabled="!quickAvailable(key)" :data-jump="key" @click="quick(key)">{{label}}</button><span>检测 <i class="detection"></i> 风险 <i class="risk"></i> 处置 <i class="emergency"></i> 关键 <i class="critical"></i> 稳定 <i class="recovery"></i></span></div>
 <p v-if="store.currentGap" class="review-warning" data-testid="replay-gap">该时段历史采样缺失（{{elapsed(store.currentGap.from_time)}}—{{elapsed(store.currentGap.to_time)}}），保持前次有效观测，不补造中间状态。</p><p v-if="missing.length" class="review-notice">历史字段未记录：{{missing.join('、')}}。可用字段仅使用该事件较早的有效记录。</p><p v-if="!store.snapshots.length&&!store.loading" class="review-warning">此事件尚无可回放快照，可查看事件时间轴与已有档案。</p>
 </section>
 <section class="panel review-trends"><header><h3>已保存的历史观测</h3><small>实线：历史采样 · 橙色游标：回放时刻 · 阴影：采样缺口</small></header><div class="review-toolbar"><button v-for="(metric,index) in chartTabs" :key="metric.metric" :class="{active:chartTab===index}" @click="chartTab=index">{{metric.label}} · {{metric.unit}}</button></div><ReplayChart :snapshots="store.snapshots" :gaps="store.gaps" :current-time="store.currentTime" :start-time="store.startTime" :metric="tab.metric" :label="tab.label" :unit="tab.unit" @seek="time=>{store.pause();store.seek(time)}"/><small>点击图表跳转 · {{store.snapshots.length}} 条快照 · 读取 {{number(store.replay?.metadata.latency_ms)}} ms</small></section>
 <div class="review-bottom-grid"><section class="panel"><header><h3>全过程时间轴</h3><small>{{store.timelineEvents.length}} 个持久化节点</small></header><ol class="review-timeline" data-testid="review-timeline"><li v-for="event in store.timelineEvents" :key="event.id" :class="[tone(event.event_type),{current:activeTimeline?.id===event.id}]"><button @click="jump(event)" :disabled="event.simulation_time===null"><time>{{date(event.event_time)}} · T+{{event.simulation_time===null?'未记录':elapsed(event.simulation_time)}}</time><strong>{{event.title}}</strong><p>{{event.description}}</p></button></li></ol></section>
 <section class="panel" data-testid="review-metrics"><header><h3>事故指标</h3><small>来自数据库历史</small></header><dl class="review-metrics"><div v-for="([key,value]) in selectedPeaks" :key="key"><dt>{{peakLabels[key]}}</dt><dd>{{number(value)}}</dd></div><div v-for="(label,key) in responseLabels" :key="key"><dt>{{label}}</dt><dd>{{elapsed(store.metrics?.response_metrics?.[key])}}</dd></div></dl><p class="review-muted">响应时间按原始记录的墙钟时间计算；回放使用仿真时间。响应耗时从检测到首次执行，稳定耗时从开始到稳定。</p></section></div>
 <section class="panel review-response" data-testid="review-response"><header><h3>处置效果与当时决策</h3><small>比较结果保留当时环境假设</small></header><p>{{store.metrics?.response_effect?.environment_note??'未记录处置前后对照。'}}</p><div class="review-bottom-grid"><article><h4>首次执行前观测</h4><RecordValue :value="effect(store.metrics?.response_effect?.before)"/></article><article><h4>后续最新已保存观测</h4><RecordValue :value="effect(store.metrics?.response_effect?.after)"/></article></div><h4>实际执行记录</h4><p v-if="!executionCards.length" class="review-muted">未记录执行。</p><article v-for="execution in executionCards" :key="execution.id" class="review-execution"><RecordValue :value="briefExecution(execution.data)"/></article>
 <details v-for="comparison in comparisons" :key="comparison.id" class="review-comparison"><summary>当时方案比较 · {{comparison.id.slice(0,8)}}</summary><p>{{comparison.data.assumption??comparison.data.method??'已有持久化比较'}}</p><div v-if="isFlood" class="review-table-wrap"><table><thead><tr><th>分支</th><th>期末水位 cm</th><th>期末风险</th><th>资源指数</th></tr></thead><tbody><tr v-for="branch in branches(comparison.data)" :key="String(branch.plan_code)"><td>{{branch.plan_code}}</td><td>{{number(branch.final_water_level)}}</td><td>{{number(branch.final_risk_score)}}</td><td>{{number(branch.resource_cost_score)}}</td></tr></tbody></table></div><div v-else class="review-table-wrap"><table><thead><tr><th>候选</th><th>阀门</th><th>影响建筑</th><th>服务损失指数</th></tr></thead><tbody><tr v-for="option in rows(comparison.data.options)" :key="String(option.id)"><td>{{option.id}}</td><td>{{Array.isArray(option.valves)?option.valves.join('、'):'未记录'}}</td><td>{{rows(option.affectedBuildings).map(b=>b.buildingName).join('、')}}</td><td>{{number(option.estimatedServiceLoss)}}</td></tr></tbody></table></div></details>
 </section>
 <section v-if="isFlood" class="panel" data-testid="review-prediction"><header><h3>本事件预测误差</h3><small>仅统计本事件已到期且有实际观测的预测</small></header><p>{{prediction?.message??'样本不足'}}</p><div class="review-prediction-stats"><span>有效样本 <b>{{prediction?.samples??0}}</b></span><span>ML 水位 MAE <b>{{number(prediction?.water_mae)}} cm</b></span><span>ML 风险 MAE <b>{{number(prediction?.risk_mae)}} 分</b></span><span>物理水位 MAE <b>{{number(prediction?.physical_water_mae)}} cm</b></span></div><p class="review-muted">单事件误差不代表独立测试集总体指标；未到期或缺少真实后续观测的记录不计入。</p><details v-if="prediction?.items.length"><summary>查看当时预测与实际观测（{{prediction.items.length}} 条）</summary><div class="review-table-wrap review-predictions"><table><thead><tr><th>预测基准时刻</th><th>时距 min</th><th>ML 水位 cm</th><th>实际水位 cm</th><th>水位误差 cm</th><th>ML 风险</th><th>实际风险</th><th>风险误差</th></tr></thead><tbody><tr v-for="(item,index) in prediction.items" :key="index"><td>{{typeof item.origin_time==='string'?date(item.origin_time):number(item.origin_time)}}</td><td>{{item.horizon_minutes}}</td><td>{{number(item.predicted_water)}}</td><td>{{number(item.actual_water)}}</td><td>{{number(item.water_error)}}</td><td>{{number(item.predicted_risk)}}</td><td>{{number(item.actual_risk)}}</td><td>{{number(item.risk_error)}}</td></tr></tbody></table></div></details></section>
 <section class="panel review-work-orders" data-testid="review-work-orders"><header><h3>处置工单</h3><button v-if="store.incident&&!store.incident.work_orders?.length" :disabled="busy||['CLOSED','ABORTED'].includes(store.incident.status)" @click="action(()=>reviewApi.createWorkOrder(store.incident!.id,`${store.incident!.title}处置复核`,''),'工单已创建。')">创建主工单</button></header><p v-if="!store.incident?.work_orders?.length" class="review-muted">暂无关联工单。首次应急响应会创建主工单。</p><article v-for="order in store.incident?.work_orders" :key="order.id" class="review-work-order" :data-work-order="order.id"><div><h4>{{order.title}}</h4><small>{{order.work_order_code}} · {{workOrderStatusLabels[order.status]}}</small><p>{{order.description}}</p><p>创建 {{date(order.created_at)}} · 完成 {{date(order.completed_at)}}</p></div><label>接单班组<input :value="assignee[order.id]??order.assignee??''" :disabled="order.status!=='PENDING'" aria-label="接单班组" placeholder="例如：管网班组" @input="assignee[order.id]=($event.target as HTMLInputElement).value"/></label><label>处理结果<textarea :value="result[order.id]??order.result??''" :disabled="order.status==='COMPLETED'||order.status==='CANCELLED'" aria-label="工单处理结果" placeholder="记录实际仿真处置和仍存在的影响" @input="result[order.id]=($event.target as HTMLTextAreaElement).value"></textarea></label><div class="review-toolbar"><button v-if="order.status==='PENDING'" :disabled="busy" @click="updateOrder(order,'ASSIGNED')">接单</button><button v-if="order.status==='ASSIGNED'" :disabled="busy" @click="updateOrder(order,'IN_PROGRESS')">开始处理</button><button v-if="order.status==='IN_PROGRESS'" :disabled="busy" @click="updateOrder(order,'COMPLETED')">完成工单</button></div></article></section>
 <section class="panel review-close" data-testid="review-close"><header><h3>事件业务关闭</h3><b>{{store.incident?incidentStatusLabels[store.incident.status]:''}}</b></header><p>仅稳定中的软件仿真事故允许关闭。关闭保留设备、阀门与历史记录，不代表积水排空或供水恢复；重置演示会将未关闭事件标为已中断。</p><p v-if="store.incident?.work_orders?.some(o=>o.status!=='COMPLETED'&&o.status!=='CANCELLED')" class="review-warning">仍有未完成工单，建议先完成工单并记录遗留影响。</p><template v-if="store.incident?.status==='STABILIZING'"><label>关闭说明<textarea v-model="closeResult" aria-label="事件关闭说明" placeholder="记录稳定状态、残余影响和人工确认结果"></textarea></label><button :disabled="busy||!closeResult.trim()" @click="closeIncident">人工确认关闭事件</button></template><p v-else>{{store.incident?.status==='CLOSED'?'事件已关闭，可持续查看历史档案。':'当前状态不满足关闭条件。'}}</p></section>
 <p v-if="actionError" role="alert">{{actionError}}</p><p v-if="actionMessage" role="status">{{actionMessage}}</p>
 <section class="panel review-report" data-testid="review-report"><header><div><h3>事故复盘报告</h3><small>真实历史数据 + 固定模板 · Web Report</small></div><button :disabled="reportBusy||!store.incident" @click="generateReport">{{reportBusy?'生成中…':store.report?'重新生成报告':'生成复盘报告'}}</button></header><template v-if="store.report"><p class="review-muted">生成时间 {{date(store.report.generated_at)}} · 保存于事故档案</p><article v-for="(label,key) in {summary:'事件概况',cause_analysis:'异常与原因线索',response_analysis:'处置过程与效果',prediction_analysis:'预测表现',impact_analysis:'影响与遗留事项'}" :key="key"><h4>{{label}}</h4><p>{{store.report[key]||'未记录'}}</p></article><article><h4>改进建议</h4><ul><li v-for="lesson in store.report.lessons" :key="lesson">{{lesson}}</li></ul></article></template><p v-else class="review-muted">尚未生成报告。生成内容仅基于已保存数据，缺失项明确标注。</p></section>
 </template></main></div>
</section>
</template>
